        Assert.NotNull(world.FindInteraction("south-bank"));
        Assert.NotNull(world.FindInteraction("stones"));
    }

    [Fact]
    public void ReusingAnInteractionIdReplacesItWhereItStood()
    {
        var map = BaseMap();
        Write("starter.d/010-stones.json", """
        {
          "locations": [
            { "index": 1, "connections": {},
              "interactions": [
                { "interactionId": "stones", "triggers": ["*stones*"],
                  "actions": [ { "action": "describe", "parameters": ["They spell a word."] } ] }
              ] }
          ]
        }
        """);

        var world = World.Load(map);
        var location = world.FindLocation(1)!;

        Assert.Single(location.Interactions);
        Assert.Contains("They spell a word.", location.Interactions[0].Actions[0].Parameters);
    }

    [Fact]
    public void FragmentsAreAppliedInFilenameOrder()
    {
        var map = BaseMap();
        Write("starter.d/010-first.json", """
        { "locations": [ { "index": 1, "name": "First", "connections": {} } ] }
        """);
        Write("starter.d/020-second.json", """
        { "locations": [ { "index": 1, "name": "Second", "connections": {} } ] }
        """);

        var world = World.Load(map);

        Assert.Equal("Second", world.FindLocation(1)!.Name);
    }
}

using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// A map that can only be written back whole is a map nobody can safely edit.
/// Fragments are the way in: small files beside the big one, folded in at load.
/// They add and they replace; they never blank.
/// </summary>
public class MapFragmentTests : IDisposable
{
    private readonly string _directory =
        Path.Combine(Path.GetTempPath(), "og-fragments-" + Guid.NewGuid().ToString("n"));

    private const string Base = """
    {
      "name": "fragmented",
