        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, content);
        return path;
    }

    private string BaseMap() => Write("starter.json", Base);

    public void Dispose()
    {
        if (Directory.Exists(_directory))
