        {
          "locations": [
            { "index": 1, "connections": {},
              "interactions": [
                { "interactionId": "south-bank", "triggers": ["*south*"],
                  "actions": [ { "action": "describe", "parameters": ["No path that way."] } ] }
              ] }
          ]
        }
        """);

        var world = World.Load(map);

        Assert.Equal(2, world.FindLocation(1)!.Interactions.Count);
